{"implementation": "def solve(case):
    # Validate top-level structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if "threshold" not in case:
        raise ValueError("Missing required field: threshold")
    if "calls" not in case:
        raise ValueError("Missing required field: calls")

    threshold = case["threshold"]
    calls = case["calls"]

    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    required_fields = ["call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"]

    accepted_call_ids = []
    diagnostics = []

    for i, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f"calls[{i}] must be a dict")
        for field in required_fields:
            if field not in call:
                raise ValueError(f"calls[{i}] missing required field: {field}")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(loss_without, (int, float)):
            raise ValueError(f"{call_id}: loss_without_call must be numeric")
        if not isinstance(loss_with, (int, float)):
            raise ValueError(f"{call_id}: loss_with_call must be numeric")
        if not isinstance(prediction_tokens, int) or prediction_tokens < 1:
            raise ValueError(f"{call_id}: prediction_tokens must be a positive integer")
        if not isinstance(parseable, bool):
            raise ValueError(f"{call_id}: parseable must be a boolean")

        # Stronger counterfactual: gain from using the API call
        gain = loss_without - loss_with

        # Normalize by prediction token count (normalized future-token weight)
        normalized_gain = gain / prediction_tokens

        # Inclusive threshold: accept if parseable AND normalized_gain >= threshold
        accepted = parseable and (normalized_gain >= threshold)

        if accepted:
            accepted_call_ids.append(call_id)

        # Round per-call diagnostics to 8 decimal places
        diagnostics.append({
            "call_id": call_id,
            "gain": round(gain, 8),
            "normalized_gain": round(normalized_gain, 8),
            "parseable": parseable,
            "accepted": accepted
        })

    return {
        "accepted_call_ids": accepted_call_ids,
        "total_accepted": len(accepted_call_ids),
        "total_calls": len(calls),
        "diagnostics": diagnostics
    }
